// patio slab near outdoor unit
const slabMat = new THREE.MeshStandardMaterial({ color:0x9aa0a6, roughness:0.85 });
const slab = new THREE.Mesh(new THREE.BoxGeometry(3.4,0.08,2.6), slabMat);
slab.position.set(2.4, 0.04, 0);
slab.receiveShadow = true; slab.castShadow = false;
scene.add(slab);

// room floor
floorMat = new THREE.MeshStandardMaterial({ map: woodFloorTexture(), roughness:0.7, metalness:0.02 });
const floor = new THREE.Mesh(new THREE.BoxGeometry(5.0,0.1,5.6), floorMat);
floor.position.set(-2.55, -0.05, 0);
floor.receiveShadow = true;
scene.add(floor);

// ceiling
const ceilMat = new THREE.MeshStandardMaterial({ color:0xf3efe5, roughness:0.95 });
const ceiling = new THREE.Mesh(new THREE.BoxGeometry(5.0,0.1,5.6), ceilMat);
ceiling.position.set(-2.55, 3.0, 0);
ceiling.receiveShadow = true;
scene.add(ceiling);

// back wall
const backWallMat = new THREE.MeshStandardMaterial({ map: plasterTexture(), roughness:0.92 });
const backWall = new THREE.Mesh(new THREE.BoxGeometry(5.0,3.0,0.12), backWallMat);
backWall.position.set(-2.55, 1.5, -2.72);
backWall.receiveShadow = true; backWall.castShadow = true;
scene.add(backWall);

// end cap wall
const endWall = new THREE.Mesh(new THREE.BoxGeometry(0.12,3.0,5.6), backWallMat);
endWall.position.set(-5.05, 1.5, 0);
endWall.receiveShadow = true;
scene.add(endWall);

// dividing wall (the star of the show) - 6 face materials so indoor/outdoor faces differ
wallInteriorMat = new THREE.MeshStandardMaterial({ map: plasterTexture(), roughness:0.9 });
wallExteriorMat = new THREE.MeshStandardMaterial({ map: sidingTexture(), roughness:0.75, metalness:0.05 });
const wallEdgeMat = new THREE.MeshStandardMaterial({ color:0xcac2ae, roughness:0.9 });
const wallMats = [wallExteriorMat, wallInteriorMat, wallEdgeMat, wallEdgeMat, wallEdgeMat, wallEdgeMat]; // +x,-x,+y,-y,+z,-z
const dividingWall = new THREE.Mesh(new THREE.BoxGeometry(0.3,3.0,5.6), wallMats);

