/* ---------------------------------------------------------------------- */
/* Particle systems                                                       */
/* ---------------------------------------------------------------------- */
const REFRIGERANT_COUNT = 90;
const ROOM_AIR_COUNT = 110;
const OUTDOOR_AIR_COUNT = 110;
const DROPLET_COUNT = 26;
const HEAT_ARROW_COUNT = 22;

function buildParticleSystems(){
  const refGeo = new THREE.SphereGeometry(0.026, 10, 8);
  const refMat = new THREE.MeshStandardMaterial({ roughness:0.3, metalness:0.1, emissive:0x222222, emissiveIntensity:0.6 });
  refrigerantMesh = new THREE.InstancedMesh(refGeo, refMat, REFRIGERANT_COUNT);
  refrigerantMesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(REFRIGERANT_COUNT*3), 3);
  scene.add(refrigerantMesh);
  for(let i=0;i<REFRIGERANT_COUNT;i++){
    refrigerantParticles.push({ t: i/REFRIGERANT_COUNT });
  }

  const airGeo = new THREE.SphereGeometry(0.021, 8, 6);
  const roomAirMat = new THREE.MeshStandardMaterial({ color:0xffe9c2, transparent:true, opacity:0.85, roughness:0.6, emissive:0x froid });
  scene.add(0); // placeholder removed below
}

</script>
</body>

